import { randomUUID } from 'node:crypto';
import type { IncomingMessage, ServerResponse } from 'node:http';

export const REQUEST_ID_HEADER = 'x-request-id';

/** How a request gets its id: called once per request by the request logger (pino-http's genReqId). */
export type RequestIdSource = (req: IncomingMessage, res: ServerResponse) => string;

/**
 * The request id is generated by the server, always (P5 plan §8.6, P5.8; R50). An incoming X-Request-ID is ignored —
 * neither logged, nor echoed, nor stored in the activity record — because a caller controls it, and a plain-looking
 * value can still be an IP address. The id is returned in the x-request-id response header, which the proxy logs to
 * trace a request across it (P15).
 */
export const serverRequestId: RequestIdSource = (_req, res) => {
  const id = randomUUID();
  res.setHeader(REQUEST_ID_HEADER, id);
  return id;
};
